-- Postforme project credentials remain server-side. Persist only local ownership and safe projections.
CREATE TABLE app.postforme_bindings(organization_id uuid NOT NULL,brand_id uuid NOT NULL,platform text NOT NULL,external_id uuid NOT NULL UNIQUE DEFAULT gen_random_uuid(),PRIMARY KEY(organization_id,brand_id,platform),FOREIGN KEY(organization_id,brand_id) REFERENCES app.brands(organization_id,id));
CREATE TABLE app.postforme_attempts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,brand_id uuid NOT NULL,platform text NOT NULL,session_id uuid NOT NULL,requested_by uuid NOT NULL,expires_at timestamptz NOT NULL DEFAULT now()+interval '30 minutes',completed_at timestamptz,FOREIGN KEY(organization_id,brand_id,platform) REFERENCES app.postforme_bindings(organization_id,brand_id,platform));
CREATE TABLE app.postforme_accounts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,brand_id uuid NOT NULL,platform text NOT NULL,remote_id text NOT NULL UNIQUE,username text NOT NULL,profile_photo_url text,status text NOT NULL CHECK(status IN ('connected','disconnected','disconnecting')),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,brand_id,id),FOREIGN KEY(organization_id,brand_id,platform) REFERENCES app.postforme_bindings(organization_id,brand_id,platform));
CREATE TABLE app.postforme_publications(id uuid PRIMARY KEY,organization_id uuid NOT NULL,brand_id uuid NOT NULL,account_id uuid NOT NULL,slot_id uuid NOT NULL,revision integer NOT NULL,request_key text NOT NULL,request_hash text NOT NULL,proof jsonb NOT NULL,caption text NOT NULL,scheduled_at timestamptz NOT NULL,phase text NOT NULL CHECK(phase IN ('preparing','submitting','accepted','unknown','rejected','canceled')),remote_id text,observed_state text NOT NULL DEFAULT 'unconfirmed' CHECK(observed_state IN ('unconfirmed','scheduled','processing','published','failed')),release_url text,error_code text,last_checked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,brand_id,request_key),FOREIGN KEY(organization_id,brand_id,account_id) REFERENCES app.postforme_accounts(organization_id,brand_id,id),FOREIGN KEY(organization_id,brand_id,slot_id) REFERENCES app.content_slots(organization_id,brand_id,id),FOREIGN KEY(organization_id,brand_id) REFERENCES app.brands(organization_id,id));
CREATE UNIQUE INDEX postforme_active_slot ON app.postforme_publications(brand_id,slot_id,account_id) WHERE phase NOT IN ('rejected','canceled');
CREATE TABLE app.postforme_analytics(organization_id uuid NOT NULL,brand_id uuid NOT NULL,account_id uuid NOT NULL,posts jsonb NOT NULL DEFAULT '[]',updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(organization_id,brand_id,account_id),FOREIGN KEY(organization_id,brand_id,account_id) REFERENCES app.postforme_accounts(organization_id,brand_id,id));
DO $$ DECLARE tab text; BEGIN FOREACH tab IN ARRAY ARRAY['postforme_bindings','postforme_attempts','postforme_accounts','postforme_publications','postforme_analytics'] LOOP
 EXECUTE format('ALTER TABLE app.%I ENABLE ROW LEVEL SECURITY',tab);EXECUTE format('ALTER TABLE app.%I FORCE ROW LEVEL SECURITY',tab);
 EXECUTE format('GRANT SELECT,INSERT,UPDATE ON app.%I TO desvio_app',tab);
 EXECUTE format('CREATE POLICY member_read ON app.%I FOR SELECT TO desvio_app USING(app.can_access(organization_id) AND app.brand_matches(brand_id) AND app.business_access(organization_id,brand_id))',tab);
 EXECUTE format('CREATE POLICY manager_insert ON app.%I FOR INSERT TO desvio_app WITH CHECK(app.brand_matches(brand_id) AND app.social_manager(organization_id,brand_id))',tab);
 EXECUTE format('CREATE POLICY manager_update ON app.%I FOR UPDATE TO desvio_app USING(app.brand_matches(brand_id) AND app.social_manager(organization_id,brand_id)) WITH CHECK(app.brand_matches(brand_id) AND app.social_manager(organization_id,brand_id))',tab);
 END LOOP;END $$;
